# Flat spot illustrations for the workbooks. All drawn here, viewBox 0 0 80 64.
N, B, L, P, SK, G, O, BR, Y, GR = '#002761', '#0056d2', '#e8eef7', '#d81b60', '#f2c9a0', '#4f9a3a', '#f6b26b', '#8d5a3b', '#f4c430', '#94a3b8'

def svg(body):
    return f'<svg viewBox="0 0 80 64" xmlns="http://www.w3.org/2000/svg">{body}</svg>'

def person(x, y, s=1, shirt=B, hair='#3b2a20'):
    return (f'<g transform="translate({x},{y}) scale({s})"><path d="M-14 30 C-14 12 14 12 14 30Z" fill="{shirt}"/>'
            f'<circle cx="0" cy="0" r="10" fill="{SK}"/><path d="M-10 -1 C-10 -13 10 -13 10 -1 C7 -7 -7 -7 -10 -1Z" fill="{hair}"/>'
            f'<circle cx="-3.5" cy="0" r="1.2" fill="#0f1114"/><circle cx="3.5" cy="0" r="1.2" fill="#0f1114"/>'
            f'<path d="M-3 4.5 Q0 7 3 4.5" stroke="#0f1114" stroke-width="1.1" fill="none"/></g>')

