def en_icon(L):
    t = (L.get('theme', '') + ' ' + L.get('title', '')).lower()
    rules = [('parts of speech', 'abc'), ('sentence pattern', 'blocks'), ('build an english sentence', 'blocks'), ('pronoun', 'catbox'), ('tense', 'timeline'),
             ('conjunction', 'links'), ('joining', 'links'), ('home', 'house'), ('town', 'map'), ('direction', 'map'), ('food', 'food'), ('café', 'food'),
             ('shopping', 'bag'), ('clothes', 'bag'), ('right now', 'camera'), ('picture', 'camera'), ('weekend', 'calendar'), ('yesterday', 'calendar'),
             ('school', 'school'), ('travel', 'plane'), ('story', 'plane'), ('health', 'health'), ('clinic', 'health'), ('doctor', 'health'),
             ('plan', 'calendar'), ('career', 'briefcase'), ('job', 'briefcase'), ('compar', 'scale'), ('universit', 'cap'), ('studying in korea', 'cap'),
             ('rules', 'cap'), ('advice', 'cap'), ('email', 'email'), ('writing to', 'email'), ('polite', 'speech'), ('goal', 'target'), ('strength', 'target'),
             ('personality', 'target'), ('interview', 'interview'), ('point, reason', 'interview'), ('statement', 'document'), ('experience', 'star'),
             ('have you ever', 'star'), ('introduc', 'hello'), ('hello', 'hello'), ('personal information', 'idcard'), ('phone number', 'idcard'),
             ('family', 'family'), ('routine', 'clock'), ('a day in', 'clock'), ('hobb', 'ball'), ('free time', 'ball'), ('love doing', 'ball'),
             ('phone', 'phone'), ('review', 'star')]
    for k, v in rules:
        if k in t:
            return I[v]
    return {'Writing': I['pencil'], 'Speaking': I['speech'], 'Reading': I['book'], 'Listening': I['headphones']}.get(L.get('folder'), I['book'])
